import csv
import os
import argparse

# ==========================================
# 1. GLOBAL PATHS AND CONFIGURATIONS
# ==========================================
CURR_DIR = os.path.dirname(os.path.abspath(__file__))
BASE_DIR = os.path.join(CURR_DIR, '..')

# Experiment mapping (must match the names generated by the validation script)
EXPERIMENT_CONFIG = {
    1: {"out_dir": "esperimento_1", "out_file": "final_validation_detailed"},
    2: {"out_dir": "esperimento_2_s75", "out_file": "final_validation_cascade"},
    3: {"out_dir": "esperimento_3", "out_file": "final_validation_cascade"},
    4: {"out_dir": "esperimento_4", "out_file": "final_validation_cascade_fold"},
    5: {"out_dir": "esperimento_5", "out_file": "final_validation_automl"},
    6: {"out_dir": "esperimento_6", "out_file": "final_validation_automl_L1"},
    7: {"out_dir": "esperimento_7", "out_file": "final_validation_automl_L2"},
}

def load_csv(filepath):
    data = []
    with open(filepath, 'r', newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            data.append(row)
    return data

# ==========================================
# 2. ANALYSIS FUNCTIONS
# ==========================================

def verify_ml_choices(domain, exp_id, log_file):
    def log(msg):
        print(msg)
        log_file.write(msg + '\n')

    cfg = EXPERIMENT_CONFIG[exp_id]
    val_file = os.path.join(CURR_DIR, cfg['out_dir'], f"{cfg['out_file']}_{domain}.csv")
    test_file = os.path.join(CURR_DIR, f"test_set_{domain}_20perc.csv")

    if not os.path.exists(val_file) or not os.path.exists(test_file):
        log(f"Error: Missing files for {domain}. Check if {val_file} and {test_file} exist.")
        return
        
    val_data = load_csv(val_file)
    test_data = load_csv(test_file)
    
    # Create an instance -> best_config mapping
    test_dict = {row['instance_name']: row['best_config_TRUE'] for row in test_data if 'instance_name' in row and 'best_config_TRUE' in row}
    
    total_slower = 0
    correct_choices = 0
    wrong_choices = []
    
    for row in val_data:
        instance = row.get('instance')
        if not instance or instance not in test_dict:
            continue
            
        ml_time = float(row.get('ml_time', 0))
        real_min_time = float(row.get('real_min_time', row.get('min_time_reale', 0))) # Fallback for old CSV columns
        ml_config = row.get('ml_config')
        best_config_true = test_dict[instance]
        
        if ml_time > real_min_time:
            total_slower += 1
            if ml_config == best_config_true:
                correct_choices += 1
            else:
                wrong_choices.append((instance, ml_time, real_min_time, ml_config, best_config_true))
                
    if total_slower == 0:
        log(f"\n[{domain}] No instances found where ml_time > real_min_time.")
        return
        
    percentage = (correct_choices / total_slower) * 100
    
    log(f"\n--- Report for {domain} ---")
    log(f"Total instances where ml_time > real_min_time: {total_slower}")
    log(f"Out of these, instances where ml_config == best_config_TRUE: {correct_choices}")
    log(f"Accuracy on slower instances: {percentage:.2f}%")
    
    if wrong_choices:
        log(f"\nExample of {len(wrong_choices)} choices not matching the 'best_config_TRUE':")
        log(f"{'Instance'.ljust(45)} | {'ml_time':>10} | {'min_time':>10} | {'ml_config':>15} | {'best_config_TRUE':>15}")
        log("-" * 105)
        for item in wrong_choices[:10]:
            log(f"{item[0][:40].ljust(45)} | {item[1]:10.2f} | {item[2]:10.2f} | {item[3]:>15} | {item[4]:>15}")


def verify_unsat(domain, exp_id, log_file):
    def log(msg):
        print(msg)
        log_file.write(msg + '\n')

    cfg = EXPERIMENT_CONFIG[exp_id]
    val_file = os.path.join(CURR_DIR, cfg['out_dir'], f"{cfg['out_file']}_{domain}.csv")
    
    if not os.path.exists(val_file):
        return

    val_data = load_csv(val_file)
    
    unsolved_instances = []
    for row in val_data:
        solved_str = row.get('solved')
        ml_time = float(row.get('ml_time', 1200))
        
        solved = (solved_str == 'True')
        solved_unsat = (solved_str == 'False' and ml_time < 1200)
        
        # Add to unsolved only if it exceeded time (not solved and not a fast UNSAT)
        if not solved and not solved_unsat:
            unsolved_instances.append(row)
    
    if not unsolved_instances:
        log(f"\n[{domain}] No instances were left unsolved by the machine learning.")
        return

    log(f"\n--- Unsolved Instances Analysis (Actually UNSAT?) for {domain} ---")
    log(f"Found {len(unsolved_instances)} instances unsolved by ML.")
    
    base_train_dir = os.path.join(BASE_DIR, "training_benchmarks_results")
    base_test_dir = os.path.join(BASE_DIR, "ijcai_benchmarks_results")
    
    unsat_count = 0
    sat_count = 0
    unknown_count = 0
    
    # Cache to avoid re-reading node_info.log for instances of the same problem
    # instance_mapping[problem][instance_name] = directory
    instance_mapping = {}

    for row in unsolved_instances:
        problem = row.get('problem')
        instance = row.get('instance')
        
        if problem not in instance_mapping:
            instance_mapping[problem] = {}
            # Search in training
            train_dir = os.path.join(base_train_dir, f"AMOSUM_{problem}_old")
            for conf_test in ["config2", "config3"]: # Use one config to find the ID
                conf_dir = os.path.join(train_dir, conf_test)
                if os.path.exists(conf_dir):
                    for inst_dir in os.listdir(conf_dir):
                        if inst_dir.startswith("instance"):
                            node_log = os.path.join(conf_dir, inst_dir, "run1", "node_info.log")
                            if os.path.exists(node_log):
                                with open(node_log, 'r') as f:
                                    content = f.read()
                                    for line in content.splitlines():
                                        if line.startswith("Input:"):
                                            found_instance = os.path.basename(line.strip())
                                            instance_mapping[problem][found_instance] = (train_dir, inst_dir)
                                            # For compatibility, save the full line too
                                            instance_mapping[problem][line.strip()] = (train_dir, inst_dir)
            
            # Search in testing
            test_dir = os.path.join(base_test_dir, f"AMOSUM_{problem}")
            for conf_test in ["config2", "config3"]:
                conf_dir = os.path.join(test_dir, conf_test)
                if os.path.exists(conf_dir):
                    for inst_dir in os.listdir(conf_dir):
                        if inst_dir.startswith("instance"):
                            node_log = os.path.join(conf_dir, inst_dir, "run1", "node_info.log")
                            if os.path.exists(node_log):
                                with open(node_log, 'r') as f:
                                    content = f.read()
                                    for line in content.splitlines():
                                        if line.startswith("Input:"):
                                            found_instance = os.path.basename(line.strip())
                                            instance_mapping[problem][found_instance] = (test_dir, inst_dir)
                                            instance_mapping[problem][line.strip()] = (test_dir, inst_dir)
        
        if instance in instance_mapping[problem]:
            full_dir, inst_dir = instance_mapping[problem][instance]
        else:
            log(f"Could not find node_info.log for instance: {instance}")
            continue
        
        configs = ["config2", "config3", "config4", "config5", "config6"]
        status = "UNKNOWN"
        
        for conf in configs:
            log_file_path = os.path.join(full_dir, conf, inst_dir, "run1", "stdout.log")
            if os.path.exists(log_file_path):
                try:
                    with open(log_file_path, 'r', errors='ignore') as f:
                        log_content = f.read().lower()
                        # Avoid matching "Unsat: 0.00s" from clingo stats
                        if "unsatisfiable\n" in log_content or "\nunsatisfiable" in log_content or "incoherent" in log_content or "\nunsat\n" in log_content:
                            status = "UNSAT"
                            break
                        elif "\nanswer set" in log_content or "answer set [" in log_content or "answer: 1" in log_content or "satisfiable\n" in log_content or "\nsatisfiable" in log_content:
                            status = "SAT"
                            break
                except Exception as e:
                    pass
                    
        if status == "UNSAT":
            unsat_count += 1
            log(f"[UNSAT] {problem} - {instance}")
        elif status == "SAT":
            sat_count += 1
            log(f"[SAT] {problem} - {instance}")
        else:
            unknown_count += 1
            log(f"[UNKNOWN] {problem} - {instance}")
            
    log(f"\nSummary for {domain} ML Unsolved instances:")
    log(f"Actually UNSAT: {unsat_count}")
    log(f"Actually SAT: {sat_count}")
    log(f"Always UNKNOWN (unsolved by any config): {unknown_count}")


def count_solved_testset(domain, exp_id, log_file):
    def log(msg):
        print(msg)
        log_file.write(msg + '\n')

    cfg = EXPERIMENT_CONFIG[exp_id]
    val_file = os.path.join(CURR_DIR, cfg['out_dir'], f"{cfg['out_file']}_{domain}.csv")
    
    if not os.path.exists(val_file):
        return

    # Load test set
    test_file = os.path.join(CURR_DIR, f"test_set_{domain}_20perc.csv")
    if not os.path.exists(test_file):
        return
        
    test_data = load_csv(test_file)
    test_instances = set(row['instance_name'] for row in test_data if 'instance_name' in row)
    
    val_data = load_csv(val_file)
    problem_stats = {}
    
    # Group instances by problem
    for row in val_data:
        instance = row.get('instance')
        problem = row.get('problem')
        if not instance or instance not in test_instances:
            continue
            
        solved_str = row.get('solved')
        ml_time = float(row.get('ml_time', 1200))
        
        solved_sat = (solved_str == 'True')
        solved_unsat = (solved_str == 'False' and ml_time < 1200)
        solved_ml = solved_sat or solved_unsat
        
        if problem not in problem_stats:
            problem_stats[problem] = {'ml_solved': 0, 'total': 0, 'conf_solved': {}}
            
        problem_stats[problem]['total'] += 1
        if solved_ml:
            problem_stats[problem]['ml_solved'] += 1
            
    base_train_dir = os.path.join(BASE_DIR, "training_benchmarks_results")
    base_test_dir = os.path.join(BASE_DIR, "ijcai_benchmarks_results")
    
    if domain == 'AMO':
        target_configs = {'CLINGO': '2', 'AMOCLINGO-INF-MR': '3', 'AMOCLINGO-L': '4'}
    elif domain == 'EO':
        target_configs = {'CLINGO': '2', 'EOCLINGO-INF-MR': '5', 'EOCLINGO-L': '6'}
    else:
        target_configs = {}
        
    for problem, stats in problem_stats.items():
        for conf_name in target_configs.keys():
            stats['conf_solved'][conf_name] = 0
            
        old_dir = f"AMOSUM_{problem}_old"
        new_dir = f"AMOSUM_{problem}"
        
        results_files = [
            os.path.join(base_train_dir, old_dir, "results.csv"),
            os.path.join(base_test_dir, new_dir, "results.csv")
        ]
        
        for results_file in results_files:
            if os.path.exists(results_file):
                results_data = load_csv(results_file)
                for row in results_data:
                    conf_id = row.get('config_id')
                    inst_path = row.get('instance')
                    time_val = float(row.get('perf_seconds-time-elapsed', 1200))
                    
                    # check if instance in testset
                    inst_name = os.path.basename(inst_path) if inst_path else ""
                    
                    for conf_name, target_id in target_configs.items():
                        if conf_id == target_id and inst_name in test_instances and time_val < 1200:
                            stats['conf_solved'][conf_name] += 1
                        
    log(f"\n--- Solved Instances Comparison (Single Configs vs ML) for {domain} ---")
    for problem, stats in problem_stats.items():
        log(f"Problem: {problem}")
        log(f"  Total Testset Instances: {stats['total']}")
        log(f"  Solved by ML: {stats['ml_solved']}")
        for conf_name, count in stats['conf_solved'].items():
            log(f"  Solved by {conf_name}: {count}")


# ==========================================
# 3. ENTRY POINT
# ==========================================
if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Generate ML statistics reports across experiments.")
    parser.add_argument('--domain', type=str, choices=['AMO', 'EO', 'ALL'], default='ALL', 
                        help='Choose which domain to analyze (AMO, EO, or ALL)')
    parser.add_argument('--experiment', type=str, choices=[str(i) for i in range(1, 8)] + ['ALL'], default='ALL', 
                        help='Choose experiment ID to analyze (1 to 7, or ALL)')
    
    args = parser.parse_args()
    
    domains_to_run = ['AMO', 'EO'] if args.domain == 'ALL' else [args.domain]
    experiments_to_run = list(range(1, 8)) if args.experiment == 'ALL' else [int(args.experiment)]

    for exp in experiments_to_run:
        cfg = EXPERIMENT_CONFIG[exp]
        exp_dir = os.path.join(CURR_DIR, cfg['out_dir'])
        
        # Ensure the experiment directory exists before trying to write logs into it
        if not os.path.exists(exp_dir):
            print(f"Directory {exp_dir} not found. Did you run the validation script for Experiment {exp}?")
            continue
            
        output_filename = os.path.join(exp_dir, 'ml_statistics_report.txt')
        
        with open(output_filename, 'w') as log_file:
            def log_main(msg):
                print(msg)
                log_file.write(msg + '\n')
                
            log_main(f"Final Validation Analysis for Experiment {exp}\n" + "="*50)
            
            for dom in domains_to_run:
                verify_ml_choices(dom, exp, log_file)
                verify_unsat(dom, exp, log_file)
                count_solved_testset(dom, exp, log_file)
                
        print(f"\n Report successfully saved in: {output_filename}\n")